func isValid(s string) bool {
	dic := map[byte]byte{'{': '}', '[': ']', '(': ')', '?': '?'}
	stack := []byte{'?'}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if _, ok := dic[c]; ok {
			stack = append(stack, c)
		} else if dic[stack[len(stack)-1]] != c {
			return false
		}
	}
	return len(stack) == 1
}

