func isValid(s string) bool {
	dic := map[byte]byte{')': '(', ']': '[', '}': '{'}
	stack := []byte{}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if len(stack) > 0 {
			if _, ok := dic[c]; ok {
				if stack[len(stack)-1] == dic[c] {
					stack = stack[:len(stack)-1]
				} else {
					return false
				}
			} else {
				stack = append(stack, c)
			}
		} else {
			stack = append(stack, c)
		}
	}
	return len(stack) == 0
}
